"""Generate the checked-in, standards-compliant learning notebooks without a notebook IDE."""
import json
from pathlib import Path

ROOT = Path(__file__).parents[1]
TOPICS = [
 ("00", "databricks_introduction", "Databricks Lakehouse", "Databricks combines collaborative notebooks, managed compute, governance, SQL, workflows, and Delta Lake around Apache Spark.", "Use it when teams need a governed platform for data, analytics, and AI."),
 ("01", "spark_fundamentals", "Spark Fundamentals", "Spark has a driver that plans work and executors that process partitioned data. Transformations are lazy; actions trigger a job.", "Use partition-aware thinking whenever a dataset exceeds one machine or joins require redistribution."),
 ("02", "pyspark_dataframes", "PySpark DataFrames", "A DataFrame is a distributed table with a schema. Prefer Spark built-in functions because Spark can optimize them.", "Use DataFrames for most ETL; use Python UDFs only when no native expression exists."),
 ("03", "spark_sql", "Spark SQL", "Spark SQL and the DataFrame API compile to the same optimizer. SQL is especially readable for analytical queries.", "Use temporary views for exploration and governed tables for shared production data."),
 ("04", "data_ingestion", "Data Ingestion", "Ingestion makes source data durable and observable. Explicit schemas prevent silently treating bad values as strings.", "Use idempotent ingestion so retries do not duplicate records."),
 ("05", "delta_lake", "Delta Lake", "Delta Lake adds a transaction log, ACID writes, schema controls, and version history to files in object storage.", "Use Delta for reliable tables. OPTIMIZE, VACUUM, and some management syntax are Databricks capabilities."),
 ("06", "bronze_layer", "Bronze Layer", "Bronze preserves source fidelity while adding ingestion metadata. It is the auditable boundary between sources and transformations.", "Use append-oriented raw tables; do not quietly repair source values here."),
 ("07", "silver_layer", "Silver Layer", "Silver standardizes types, names, and business rules into trustworthy entity-level datasets.", "Use MERGE upserts for incremental keys in Delta-capable environments."),
 ("08", "gold_layer", "Gold Layer", "Gold tables are purpose-built aggregates and dimensional models for reporting and downstream consumers.", "Use stable metric definitions and aggregate only at the grain consumers need."),
 ("09", "data_quality", "Data Quality", "Quality checks make assumptions measurable: non-null identifiers, uniqueness, references, and business ranges.", "Use quarantine outputs and metrics so bad records are visible instead of discarded."),
 ("10", "advanced_transformations", "Advanced Transformations", "Window functions retain row detail while calculating ranks and running totals; explode turns nested arrays into rows.", "Use SCD Type 2 when history matters; Type 1 when only the latest state matters."),
 ("11", "performance_optimization", "Performance Optimization", "Spark performance is mostly data movement: scans, shuffles, skew, and file layout. Plans reveal the real work.", "Measure before tuning; broadcast only genuinely small dimensions."),
 ("12", "structured_streaming", "Structured Streaming", "Structured Streaming executes incremental micro-batches with checkpoints tracking progress and state.", "Use watermarks to bound late-data state; Auto Loader is an optional Databricks ingestion feature."),
 ("13", "unity_catalog", "Unity Catalog", "Unity Catalog governs data through a metastore, catalog, schema, objects, permissions, lineage, and volumes.", "Use three-part names such as catalog.schema.table. This lesson is read-only by default."),
 ("14", "workflows_and_jobs", "Databricks Workflows", "Workflows orchestrate tasks with dependencies, parameters, retries, schedules, and observable failures.", "Use declarative asset bundles for versioned deployment; the included job YAML is a safe template."),
 ("15", "capstone_project", "Capstone: RetailFlow Pipeline", "This capstone turns deterministic raw RetailFlow files into Bronze, Silver, and Gold outputs with checks and an idempotent rerun.", "Use it as the production-shaped integration point for every earlier lesson."),
]
COMMON_SETUP = '''from pathlib import Path
import sys
root = Path.cwd().resolve()
while root != root.parent and not (root / "src").exists(): root = root.parent
sys.path.insert(0, str(root / "src"))
from retailflow.config import get_settings
settings = get_settings()
print(f"Project root: {root}")
'''
def md(s): return {"cell_type":"markdown", "metadata":{}, "source":s.splitlines(True)}
def code(s): return {"cell_type":"code", "execution_count":None, "metadata":{}, "outputs":[], "source":s.splitlines(True)}
def notebook(num, slug, title, concept, use):
    prefix = f"{num}_{slug}"
    cells = [md(f'''# {num} — {title}\n\n## Learning objectives\n\nBy the end, you can explain this topic, run a small RetailFlow example, inspect its result, and identify its production trade-offs.\n\n- **Why it matters:** {use}\n- **Prerequisites:** Python, SQL basics, and notebooks 00–{max(0, int(num)-1):02d} where applicable.\n- **Estimated time:** 60–90 minutes.\n- **Compatibility:** ✅ Local PySpark baseline · 🟨 Delta requires compatible Delta runtime · 🟦 Databricks-only features are labeled.\n\n## Conceptual explanation\n\n{concept}\n\nAnswer these questions as you read: what problem exists without this capability, what does Spark/Databricks do under the hood, and where can cost or correctness go wrong?'''),
    md('''## Architecture / execution diagram\n\n```mermaid\nflowchart LR\n  S[RetailFlow sources] --> B[Bronze: raw + metadata]\n  B --> Q[Quality checks / quarantine]\n  Q --> S1[Silver: clean entities]\n  S1 --> G[Gold: business metrics]\n  G --> C[SQL, dashboards, consumers]\n```\n\nText fallback: sources → Bronze (preserve) → validate/clean → Silver (trusted rows) → Gold (metrics).\n\n### What happens under the hood?\nSpark builds a logical plan from your transformations. An action such as `show`, `count`, or `write` asks the optimizer to create physical stages and tasks. A shuffle moves data between executors and is often the expensive boundary.'''),
    code(COMMON_SETUP),
    md('''## Runnable example\n\nThe following cell creates a local Spark session. On Databricks, `spark` already exists; use the existing session. `local[*]` is for learning only—it does not reproduce a distributed cluster.'''),
    code('''try:\n    spark\nexcept NameError:\n    from pyspark.sql import SparkSession\n    spark = SparkSession.builder.master("local[*]").appName("RetailFlowLearning").getOrCreate()\n\nfrom retailflow.data_generation import generate_raw_data\ngenerate_raw_data(root / "data" / "raw")\norders = spark.read.option("header", True).csv(str(root / "data" / "raw" / "orders.csv"))\nprint("Raw orders (includes one duplicate and one invalid timestamp):", orders.count())\norders.show(5, truncate=False)\nassert orders.count() == 91\n'''),
    md('''**Expected result:** the generated input contains 91 order rows. This includes intentional defects, so do not use that count as a clean business metric. If this assertion fails, delete `data/raw` and rerun the generator.\n\n**Common mistake:** calling `collect()` to inspect a large DataFrame. It transfers all rows to the driver; use `show`, `limit`, aggregation, or a filtered sample instead.'''),
    code('''from pyspark.sql import functions as F\nclean = (orders.withColumn("order_ts", F.to_timestamp("order_timestamp"))\n    .filter(F.col("order_ts").isNotNull()).dropDuplicates(["order_id"]))\nprint("Valid, unique orders:", clean.count())\nclean.groupBy("status").count().orderBy("status").show()\nclean.explain()  # Look for the aggregation / exchange boundaries in the physical plan.\n'''),
    md('''## Production note\n\nIn production, external storage and table governance are configured by your platform team. Do not depend on DBFS root or legacy mounts for new projects. With Unity Catalog, use approved external locations/volumes and three-level object names. Do not run destructive operations such as `VACUUM` without a retention and recovery policy.'''),
    md('''## Try It Yourself\n\n1. Change `dropDuplicates(["order_id"])` to `dropDuplicates()` and compare the count. Why do the results differ?\n2. Call `clean.repartition(4).rdd.getNumPartitions()` and change 4 to 1 and 8. On small local data, timing is not meaningful; inspect the partition count instead.\n3. Replace the filter with a quarantine DataFrame (`orders.filter(F.col("order_ts").isNull())`) and inspect bad rows.\n\n## Exercises\n\n### Beginner\n1. Count orders for each status.\n2. Find the invalid timestamp record.\n3. Select only `order_id` and `customer_id`.\n\n### Intermediate\n4. Build a daily order-count table.\n5. Join clean orders to order items and calculate completed revenue.\n\n### Advanced challenge\n6. Make the transformation idempotent and write a small quality-metrics table.\n\nSee `solutions/{prefix}_solutions.md` after attempting them.'''),
    md('''## Knowledge check\n\n### Conceptual\n1. Which operation triggers Spark execution?\n2. Why are schemas valuable at ingestion?\n3. What is a shuffle?\n4. Why retain Bronze data?\n5. What does Delta add over ordinary files?\n\n### Practical\n1. Where would you inspect an execution plan?\n2. How would you avoid duplicate key rows?\n3. Which input should be quarantined here?\n\n### Key takeaways\nSpark plans lazily, quality is an explicit contract, and the Medallion layers have different responsibilities. Review transformations versus actions, schema casting, and joins before proceeding.''')]
    return {"cells":cells,"metadata":{"kernelspec":{"display_name":"Python 3 (PySpark)","language":"python","name":"python3"},"language_info":{"name":"python","version":"3.9"}},"nbformat":4,"nbformat_minor":5}
for num, slug, title, concept, use in TOPICS:
    path = ROOT / "notebooks" / f"{num}_{slug}.ipynb"; path.parent.mkdir(exist_ok=True)
    path.write_text(json.dumps(notebook(num, slug, title, concept, use), indent=1) + "\n", encoding="utf-8")
    solution = ROOT / "solutions" / f"{num}_{slug}_solutions.md"; solution.parent.mkdir(exist_ok=True)
    solution.write_text(f"# Solutions — {num} {title}\n\nUse built-in Spark functions: filter invalid timestamps with `to_timestamp`, deduplicate on business keys, then aggregate after filtering `status = 'completed'`. Compare your output with the reusable functions in `src/retailflow/transformations/`.\n", encoding="utf-8")
